package com.enterprise.banking.service;

import com.enterprise.banking.repository.AccountRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AccountServiceImpl implements AccountService {

    private final AccountRepository accountRepository;

    public AccountServiceImpl(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    @Override
    @Transactional
    public void transferFunds(Long sourceId, Long targetId, double amount) {
        accountRepository.decrementBalance(sourceId, amount);
        accountRepository.incrementBalance(targetId, amount);
    }
}
